CREATE DATABASE IF NOT EXISTS harbor_house CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE harbor_house;
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('customer','admin','super_admin') NOT NULL DEFAULT 'customer',phone VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS properties (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,address VARCHAR(255),city VARCHAR(120) NOT NULL,image_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rooms (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,property_id INT UNSIGNED NOT NULL,room_number VARCHAR(30) NOT NULL,room_type VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,capacity INT NOT NULL DEFAULT 2,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_room (property_id,room_number),FOREIGN KEY (property_id) REFERENCES properties(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS hotel_bookings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,room_id INT UNSIGNED NOT NULL,check_in DATE NOT NULL,check_out DATE NOT NULL,guests INT NOT NULL DEFAULT 1,status ENUM('pending','confirmed','cancelled','completed') NOT NULL DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (room_id) REFERENCES rooms(id));
CREATE TABLE IF NOT EXISTS menu_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,description TEXT,category VARCHAR(80) NOT NULL DEFAULT 'General',price DECIMAL(10,2) NOT NULL,available BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS food_orders (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,total DECIMAL(10,2) NOT NULL DEFAULT 0,status ENUM('pending','preparing','ready','completed','cancelled') NOT NULL DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS food_order_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id INT UNSIGNED NOT NULL,menu_item_id INT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY (order_id) REFERENCES food_orders(id) ON DELETE CASCADE,FOREIGN KEY (menu_item_id) REFERENCES menu_items(id));
CREATE TABLE IF NOT EXISTS cab_bookings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id INT UNSIGNED NOT NULL,pickup_location VARCHAR(255) NOT NULL,dropoff_location VARCHAR(255) NOT NULL,pickup_at DATETIME NOT NULL,passengers INT NOT NULL DEFAULT 1,vehicle_type VARCHAR(80) NOT NULL DEFAULT 'Sedan',status ENUM('pending','confirmed','completed','cancelled') NOT NULL DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(id));
